window.Game=window.Game||{};
(()=>{
const KEY='reLife:v1',BACKUP='reLife:v1:backup',LIMIT=2*1024*1024;
function empty(){return{envelopeVersion:1,storeRevision:0,slots:{auto:null,manual1:null,manual2:null,manual3:null},profile:{endings:[],terminalRuns:[]},savedAt:new Date().toISOString()};}
function storage(){try{const s=window.localStorage,k='reLife:probe';s.setItem(k,'1');if(s.getItem(k)!=='1')throw Error('probe failed');s.removeItem(k);return s;}catch(e){return null;}}
function parse(text){if(typeof text!=='string'||new TextEncoder().encode(text).length>LIMIT)throw Error('文件超过 2 MB。');let v;try{v=JSON.parse(text);}catch{throw Error('文件不是有效 JSON。');}const e=v.envelopeVersion===1&&v.slots&&v.profile?v:null;if(!e)throw Error('存档结构或版本不受支持。');for(const [slot,entry]of Object.entries(e.slots)){if(entry&&(!['auto','manual1','manual2','manual3'].includes(slot)||Game.validate(entry.state).length))throw Error(`存档槽 ${slot} 的状态字段无效。`);}return e;}
function load(){const s=storage();if(!s)return{ok:false,code:'STORAGE_UNAVAILABLE',envelope:empty()};try{const raw=s.getItem(KEY);if(!raw)return{ok:true,envelope:empty()};try{return{ok:true,envelope:parse(raw)};}catch(primary){const backup=s.getItem(BACKUP);if(backup){try{return{ok:true,recovered:true,envelope:parse(backup),error:primary.message};}catch{}}return{ok:false,code:'CORRUPT_SAVE',error:primary.message,envelope:empty()};}}catch(e){return{ok:false,code:'STORAGE_UNAVAILABLE',error:e.message,envelope:empty()};}}
function write(env){const s=storage();if(!s)throw Error('本地存储不可用，请导出保存。');const safe=parse(JSON.stringify(env)),old=s.getItem(KEY);if(old){try{parse(old);try{s.setItem(BACKUP,old);}catch{ /* primary write may still fit */ }}catch{ /* preserve corrupt source until an explicit overwrite */ }}const text=JSON.stringify(safe);if(new TextEncoder().encode(text).length>LIMIT)throw Error('存档超过 2 MB，请导出并整理日志。');s.setItem(KEY,text);return safe;}
function save(env,state,slot='auto'){const current=load();if(!current.ok)throw Error('存档损坏或不可用；先导出或恢复后再继续。');if(current.envelope.storeRevision!==env.storeRevision)throw Error('另一标签页已更新存档；当前页面进入只读冲突状态。');const next=Game.clone(env);next.slots[slot]={state:Game.clone(state),savedAt:new Date().toISOString(),summary:{name:state.player.name,location:state.locationId,slotIndex:state.clock.slotIndex,phase:state.phase}};if(state.outcome&&!next.profile.endings.includes(state.outcome.id))next.profile.endings.push(state.outcome.id);if(state.phase==='ended'&&state.settings.permadeath&&!next.profile.terminalRuns.includes(state.runId))next.profile.terminalRuns.push(state.runId);next.storeRevision++;next.savedAt=new Date().toISOString();return write(next);}
function importText(text){return parse(text);}
function download(env){const b=new Blob([JSON.stringify(env,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='resident-evil-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadRaw(){const s=storage();if(!s)throw Error('浏览器存储不可用，无法导出原始存档。');const raw=s.getItem(KEY)||s.getItem(BACKUP);if(!raw)throw Error('没有可导出的原始存档。');const b=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='resident-evil-save-recovery.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
Game.storage={KEY,BACKUP,LIMIT,empty,load,save,write,parse,importText,download,downloadRaw};
})();
